function validate([n, x, y]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is a whole number from 2 to 10^5.';
  if (!Number.isInteger(x) || x < 1 || x > n) return 'x is a house label from 1 to n.';
  if (!Number.isInteger(y) || y < 1 || y > n) return 'y is a house label from 1 to n.';
  return null;
}

