function countOfPairs(n, x, y) {
  if (x > y) [x, y] = [y, x];
  const diff = new Array(n + 2).fill(0);
  const addRange = (lo, hi) => {
    if (lo > hi) return;
    diff[lo] += 1;
    diff[hi + 1] -= 1;
  };
  const cycle = y - x + 1;
  const bridge = Math.min(1, y - x);
  const leftTail = x - 1;
  const rightTail = n - y;
  for (let i = 1; i <= n; i++) {
    if (i < x || i > y) {
      const t = i < x ? x - i : i - y;
      const ownTail = i < x ? leftTail : rightTail;
      const otherTail = i < x ? rightTail : leftTail;
      addRange(1, t);
      addRange(1, ownTail - t);
      addRange(t + 1, t + Math.floor(cycle / 2));
      addRange(t + 1, t + Math.floor((cycle - 1) / 2));
      addRange(t + bridge + 1, t + bridge + otherTail);
    } else {
      const p = i - x;
      const toX = Math.min(p, cycle - p);
      const toY = Math.min(cycle - 1 - p, p + 1);
      addRange(1, Math.floor(cycle / 2));
      addRange(1, Math.floor((cycle - 1) / 2));
      addRange(toX + 1, toX + leftTail);
      addRange(toY + 1, toY + rightTail);
    }
  }
  const result = new Array(n).fill(0);
  let running = 0;
  for (let k = 1; k <= n; k++) {
    running += diff[k];
    result[k - 1] = running;
  }
  return result;
}

