function countOfPairs(n, x, y) {
  const adj = Array.from({ length: n + 1 }, () => []);
  for (let i = 1; i < n; i++) { adj[i].push(i + 1); adj[i + 1].push(i); }
  if (x !== y) { adj[x].push(y); adj[y].push(x); }
  const result = new Array(n).fill(0);
  for (let s = 1; s <= n; s++) {
    const dist = new Array(n + 1).fill(-1);
    dist[s] = 0;
    const queue = [s];
    for (let h = 0; h < queue.length; h++) {
      for (const v of adj[queue[h]]) if (dist[v] < 0) { dist[v] = dist[queue[h]] + 1; queue.push(v); }
    }
    for (let v = 1; v <= n; v++) if (v !== s) result[dist[v] - 1]++;
  }
  return result;
}

