function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 11);
  const x = 1 + Math.floor(rand() * n);
  const y = rand() < 0.15 ? x : 1 + Math.floor(rand() * n);
